# -*- coding: utf-8 -*-
from pathlib import Path
import base64, hashlib, os, sys, tempfile, zipfile, importlib.util, io, shutil
SHA256='e496c933074f7752b515be57fe7abf3357c83295265ce872109cf3868bf159cd'
ARCHIVE=base64.b64decode('')
if hashlib.sha256(ARCHIVE).hexdigest()!=SHA256: raise SystemExit("فشل التحقق من سلامة النسخة التنفيذية.")
root=Path(tempfile.gettempdir())/("كوانتوم_فيكتوري_نسخة_تنفيذية_"+SHA256[:16])
marker=root/".تم_الاستخراج"
required=root/"qv57"/"واجهة_كوانتوم_فيكتوري_المحركات_٥_٩.py"
if (not marker.exists()) or marker.read_text(encoding="utf-8").strip()!=SHA256 or not required.exists():
    if root.exists(): shutil.rmtree(root,ignore_errors=True)
    root.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(ARCHIVE)) as z: z.extractall(root)
    marker.write_text(SHA256,encoding="utf-8")
project=root/"qv57"
sys.path.insert(0,str(project)); os.chdir(project)
spec=importlib.util.spec_from_file_location("نفذ_الكامل",project/"Nafezu.py")
mod=importlib.util.module_from_spec(spec); sys.modules[spec.name]=mod; spec.loader.exec_module(mod)
if __name__=="__main__": mod.main()
